let player,
  generation = 0;
let silent = false;
try {
  silent = localStorage.getItem("little-builders.muted") === "1";
} catch {}
export const isMuted = () => silent;
export function demoVoiceProgress() {
  if (
    silent ||
    player?.dataset.clip !== "dig-demo" ||
    !Number.isFinite(player.duration)
  )
    return null;
  if (player.ended) return 1;
  return player.paused || player.readyState < 3
    ? null
    : player.currentTime / player.duration;
}
export function setMuted(on) {
  silent = on;
  try {
    localStorage.setItem("little-builders.muted", on ? "1" : "0");
  } catch {}
  if (on) stopVoice();
}
export function stopVoice() {
  generation++;
  player?.pause();
}
export function speak(id, onUnavailable) {
  stopVoice();
  if (silent || !id) return;
  const ticket = generation;
  // Reuse the element activated by the first tap for later animated scene changes on iPad.
  player ??= new Audio();
  player.preload = "auto";
  player.dataset.clip = id;
  player.src = new URL("./audio/" + id + ".wav?v=natural-ref1", import.meta.url).href;
  player.play().catch(() => {
    if (ticket === generation && !silent) onUnavailable?.();
  });
}
